<?php

namespace App\Models\Applicant;

use Illuminate\Database\Eloquent\Model;

/**
 * HR's decision after an applicant's assessments.
 *
 * Completing the assessments is not a verdict and neither is a set of results,
 * so what HR concluded is recorded here with its reason and the results as
 * they were presented. Corrections supersede rather than overwrite.
 */
class AssessmentDecision extends Model
{
    protected $connection = 'applicant';
    protected $table = 'tblapp_assessment_decisions';

    // live_application_id is generated by the database from superseded_at;
    // writing it is an error, so it can never be mass-assigned.
    protected $guarded = ['id', 'live_application_id'];

    protected $casts = [
        'results_snapshot' => 'array',
        'decided_at' => 'datetime',
        'superseded_at' => 'datetime',
    ];

    /** Carry on to the next round. Changes nothing about the application. */
    public const PROCEED = 'proceed';

    /**
     * Wait — for a retake, a second opinion, another posting.
     *
     * A real answer rather than an absence of one: without it HR would have to
     * choose between advancing somebody they are unsure about and ending it.
     */
    public const HOLD = 'hold';

    /** Do not carry on with this application. */
    public const STOP = 'stop';

    public const DECISIONS = [self::PROCEED, self::HOLD, self::STOP];

    public function application()
    {
        return $this->belongsTo(ApplicantApplication::class, 'application_id');
    }

    public function scopeLive($query)
    {
        return $query->whereNull('superseded_at');
    }
}
